// Selector. vertexMask = CGxDevice::m_primVertexMask (bit GxVA_*), numTexcoords = count of TEXCOORD
// attributes in it (capped at 2), lighting = the value IStateSyncLights would give Ds_Lighting
// (true in ambient-only mode too).
// GxVA bits: Position 0, BlendWeight 1, BlendIndices 2, Normal 3, Color0 4, Color1 5, TexCoord0.. 6..
static inline uint32_t FfSelectVs(uint32_t vertexMask, bool lighting)
{
    uint32_t n  = (vertexMask >> 3) & 1;
    uint32_t c0 = (vertexMask >> 4) & 1;
    uint32_t c1 = (vertexMask >> 5) & 1;
    uint32_t t  = ((vertexMask >> 6) & 1) + ((vertexMask >> 7) & 1);  // ponytail: TEXCOORD2+ ignored
    return (lighting ? 24 : 0) + n * 12 + c0 * 6 + c1 * 3 + t;
}

// texEnabled = CGxDeviceD3d::m_texEnabled[0..1] (a texture is bound on the stage).
static inline uint32_t FfSelectPs(bool texEnabled0, bool texEnabled1)
{
    return texEnabled0 ? (texEnabled1 ? 2 : 1) : 0;
}
